#include "Data/GiroAdapter.h"

#include <cmath>
#include <cstdio>
#include <string>

static int g_failures = 0;

static void expectNear(const char* what, double got, double want, double tol) {
    const bool ok = std::fabs(got - want) <= tol;
    if (!ok) ++g_failures;
    std::printf("  %-52s got %12.4f  want %12.4f  tol %7.4f  [%s]\n",
                what, got, want, tol, ok ? "OK" : "FAIL");
}

static void expectTrue(const char* what, bool cond) {
    if (!cond) ++g_failures;
    std::printf("  %-52s [%s]\n", what, cond ? "OK" : "FAIL");
}

